Here's a robust phone number cleaner (JavaScript, no dependencies):

```javascript
function cleanPhoneNumber(input) {
  if (input == null) return null;
  let s = String(input).trim();
  if (!s) return null;

  // Keep a leading + if present, strip everything else non-digit
  const hasPlus = s.startsWith('+');
  let digits = s.replace(/\D/g, '');

  if (!digits) return null;

  // Drop a trailing extension marker fragment that regex may have swallowed in
  // (e.g. "x123" / "ext. 45") — handled before stripping by splitting first.
  // Re-derive from original to separate extension cleanly:
  const extMatch = s.match(/(?:x|ext\.?|extension)\s*(\d+)\s*$/i);
  let extension = extMatch ? extMatch[1] : null;
  if (extMatch) {
    s = s.slice(0, extMatch.index);
    digits = s.replace(/\D/g, '');
  }

  if (!digits) return null;

  // Normalize US/Canada numbers: 10 digits, or 11 starting with 1
  let country = null;
  let national = digits;
  if (hasPlus) {
    // Assume whatever country code is present stays as-is (no country DB)
    country = digits.slice(0, digits.length - 10) || null;
    national = digits.slice(-10);
  } else if (digits.length === 11 && digits.startsWith('1')) {
    country = '1';
    national = digits.slice(1);
  } else if (digits.length === 10) {
    national = digits;
  } else {
    // Unknown/invalid length — return what we have, flagged
    return {
      raw: input,
      digits,
      valid: false,
      reason: `expected 10 or 11 digits, got ${digits.length}`,
    };
  }

  if (national.length !== 10 || /^0|^1/.test(national[0])) {
    return {
      raw: input,
      digits,
      valid: false,
      reason: 'national number must be 10 digits not starting with 0 or 1',
    };
  }

  const area = national.slice(0, 3);
  const exchange = national.slice(3, 6);
  const line = national.slice(6, 10);

  return {
    raw: input,
    valid: true,
    country: country || '1',
    e164: `+${country || '1'}${national}`,
    formatted: `(${area}) ${exchange}-${line}`,
    extension,
  };
}

module.exports = { cleanPhoneNumber };
```

**Handles:** parentheses, dashes, dots, spaces, leading `+`/`1`, extensions (`x123`, `ext. 45`), `null`/empty/non-string input, and numbers that don't resolve to a valid 10-digit US/Canada number (returns `valid: false` with a reason instead of throwing or silently mangling the number).

