Here's a small "time ago" formatter:

```js
/**
 * Formats a date as a short, human-readable "time ago" string.
 * @param {Date|string|number} date - the past date
 * @param {Date} [now] - reference time (defaults to now)
 * @returns {string} e.g. "just now", "5m ago", "3h ago", "2d ago", "4mo ago", "1y ago"
 */
function timeAgo(date, now = new Date()) {
  const then = date instanceof Date ? date : new Date(date);
  const seconds = Math.max(0, Math.floor((now - then) / 1000));

  const units = [
    { limit: 60, label: () => 'just now' },
    { limit: 3600, divisor: 60, suffix: 'm' },
    { limit: 86400, divisor: 3600, suffix: 'h' },
    { limit: 2592000, divisor: 86400, suffix: 'd' },
    { limit: 31536000, divisor: 2592000, suffix: 'mo' },
    { limit: Infinity, divisor: 31536000, suffix: 'y' },
  ];

  for (const unit of units) {
    if (seconds < unit.limit) {
      if (unit.label) return unit.label();
      return `${Math.floor(seconds / unit.divisor)}${unit.suffix} ago`;
    }
  }
}

module.exports = { timeAgo };
```

