Here's a practical email validator (TypeScript/JavaScript) that balances correctness with usability — full RFC 5322 is impractically permissive, so this checks structure, length limits, and common edge cases:

```javascript
function isValidEmail(email) {
  if (typeof email !== 'string') return false;

  const trimmed = email.trim();
  if (trimmed.length === 0 || trimmed.length > 254) return false;

  const atIndex = trimmed.lastIndexOf('@');
  if (atIndex < 1 || atIndex === trimmed.length - 1) return false;

  const local = trimmed.slice(0, atIndex);
  const domain = trimmed.slice(atIndex + 1);

  if (local.length > 64) return false;
  if (local.startsWith('.') || local.endsWith('.') || local.includes('..')) return false;

  const localPattern = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+$/;
  if (!localPattern.test(local)) return false;

  if (domain.length > 253) return false;
  if (domain.startsWith('-') || domain.startsWith('.') || domain.endsWith('.')) return false;
  if (!domain.includes('.')) return false;

  const domainPattern = /^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
  if (!domainPattern.test(domain)) return false;

  const tld = domain.slice(domain.lastIndexOf('.') + 1);
  if (tld.length < 2 || /^\d+$/.test(tld)) return false;

  return true;
}
```

